SOURCE='"""Draft Gin-only release; root reviews/fills exact post-Encore spec before use.\n\nNo broker/Encore/config writes and no database operations. Stage is separate\nfrom apply. PM2 restarts the existing ID without --update-env or delete/start.\nPython 3.11 required. Never print subprocess output or private state.\n"""\nimport argparse,hashlib,json,os,pathlib,re,shutil,subprocess,time,urllib.request\nimport fcntl\n\nROOT=pathlib.Path(\'/opt/tp-community-actions\')\nLOCK=ROOT/\'deployment.lock\'\nBINARY=pathlib.Path(\'/home/thingspanel/thingspanel-backend-community/thingspanel-backend-community\')\nPM2=\'/root/.local/share/pnpm/pm2\'\nPROCESS=\'thingspanel-backend-community\'\nCANDIDATE=\'1702cc2daf9267d590c9d3e0f41fb56cdc02b4bd\'\nBASE=\'1af192946db407e05909827ce627f1f82755640e\'\nCAS=\'05a6c75e99afbcc01987f0f219ac7704a9bfa01a\'\nCOMMAND=\'47405bfd51eba9f436231744de9a123d4278152d\'\nENCORE=\'db078b3e47af72338c856d38dd676b55e20660fa\'\nENCORE_STAGE=ROOT/\'q09-encore-db078-ci43350641612\'\nOLD_SHA=\'24a1b2a0d0c33c0f98bb9b5c8eaea468620894b820b1ab9d4cd68f0ee65c9723\'\nOLD_PID=2825348\nPM_ID=25\nENCORE_IMAGE=\'sha256:d284d82d112a0f12c1038aa4dfb7fd2427b38a4c0a49bb6c51078242733e9154\'\nENCORE_CONTAINER=\'607a26929ccd73dce17c585cce17e13803dd9745692c5630e00f083dc37659a3\'\nMANIFEST_SHA=\'267894fa36219c31f59fe46eee89794a4915cf7c9f55809823302eb1cbb84874\'\nNEXT_SHA=\'3ecc0d5ba51d6bd8a83e468abce5e72a8232c03ab53b9ef249556980830c2696\'\nEXPECTED_CHANGES={\n \'internal/api/command_set_log.go\',\'internal/api/device_config.go\',\'internal/api/device_config_metadata_test.go\',\n \'internal/brokersemantic/command.go\',\'internal/dal/device_config_metadata.go\',\'internal/dal/device_config_metadata_owner.go\',\n \'internal/dal/device_config_metadata_postgres_test.go\',\'internal/middleware/cors.go\',\'internal/model/device_config_version.go\',\n \'internal/model/device_config_version_test.go\',\'internal/service/command_data.go\',\'internal/service/command_durable.go\',\n \'internal/service/command_expected.go\',\'internal/service/device_config.go\',\'internal/service/expected_data.go\',\n \'internal/service/expected_data_ingress.go\',\'internal/service/native_command_owner_validation.go\',\n \'internal/service/native_command_owner_validation_test.go\',\'internal/service/native_command_validation.go\',\n \'internal/service/native_command_validation_test.go\',\n}\n\ndef sha(path):\n h=hashlib.sha256()\n with pathlib.Path(path).open(\'rb\') as f:\n  for chunk in iter(lambda:f.read(1048576),b\'\'):h.update(chunk)\n return h.hexdigest()\n\ndef fingerprint(value):return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(\',\',\':\')).encode()).hexdigest()\n\ndef run(args,timeout=30):\n p=subprocess.run([str(x) for x in args],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=timeout)\n if p.returncode:raise RuntimeError(\'subprocess-failed\')\n return p.stdout\n\ndef private(path,data):\n fd=os.open(str(path),os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)\n with os.fdopen(fd,\'wb\') as f:f.write(data);f.flush();os.fsync(f.fileno())\n\ndef record(path,value):private(path,json.dumps(value,indent=2).encode())\n\ndef checked_file(record):\n p=pathlib.Path(record[\'path\'])\n if record.get(\'exists\') is False:\n  if p.exists() or p.is_symlink():raise RuntimeError(\'preserved-absent-file-drift\')\n elif p.is_symlink() or not p.is_file() or sha(p)!=record[\'sha256\']:\n  raise RuntimeError(\'preserved-file-drift\')\n\ndef process():\n rows=[x for x in json.loads(run([PM2,\'jlist\'])) if x.get(\'name\')==PROCESS]\n if len(rows)!=1 or rows[0].get(\'pm_id\')!=PM_ID:raise RuntimeError(\'PM2-process-identity-drift\')\n return rows[0]\n\ndef process_contract(p):\n e=p[\'pm2_env\'];env=dict(e.get(\'env\') or {})\n env.update({k:v for k,v in e.items() if k.upper()==k and isinstance(v,(str,int,float))})\n fixed={k:e.get(k) for k in (\'pm_exec_path\',\'pm_cwd\',\'exec_interpreter\',\'exec_mode\',\'args\',\'node_args\',\'autorestart\',\'restart_delay\',\'max_memory_restart\',\'min_uptime\',\'max_restarts\',\'kill_timeout\',\'wait_ready\',\'listen_timeout\',\'merge_logs\',\'log_date_format\',\'uid\',\'gid\')}\n return fingerprint({\'name\':p[\'name\'],\'pm_id\':p[\'pm_id\'],\'env\':env,\'fixed\':fixed})\n\ndef inspect(name):return json.loads(run([\'docker\',\'inspect\',name]))[0]\n\ndef preserve(spec):\n for f in spec[\'preserved_files\']:checked_file(f)\n for e in spec[\'preserved_containers\']:\n  c=inspect(e[\'name\'])\n  if c[\'Id\']!=e[\'id\'] or c[\'Image\']!=e[\'image_id\'] or not c[\'State\'][\'Running\']:raise RuntimeError(\'non-Gin-container-drift\')\n  if \'restart_count\' in e and c[\'RestartCount\']!=e[\'restart_count\']:raise RuntimeError(\'non-Gin-container-restart\')\n e=spec[\'encore_candidate\']\n if e.get(\'container_id\')!=ENCORE_CONTAINER or e.get(\'image_id\')!=ENCORE_IMAGE:raise RuntimeError(\'unreviewed-Encore-candidate\')\n if any(not e.get(k) for k in (\'container_id\',\'image_id\',\'compose_sha256\',\'checksums_sha256\')):raise RuntimeError(\'unresolved-post-Encore-baseline\')\n staged=json.loads((ENCORE_STAGE/\'state.private.json\').read_text())\n applied=json.loads((ENCORE_STAGE/\'applied.private.json\').read_text())\n if staged[\'tooling_commit\']!=ENCORE or staged[\'checksums_sha256\']!=e[\'checksums_sha256\'] or staged[\'image_id\']!=e[\'image_id\']:\n  raise RuntimeError(\'required-Encore-stage-identity-mismatch\')\n if applied[\'container_id\']!=e[\'container_id\'] or applied[\'image_id\']!=e[\'image_id\']:raise RuntimeError(\'required-Encore-apply-identity-mismatch\')\n c=inspect(\'tp-community-main-47-encore-api-1\')\n if c[\'Id\']!=e[\'container_id\'] or c[\'Image\']!=e[\'image_id\'] or not c[\'State\'][\'Running\'] or c[\'RestartCount\']:\n  raise RuntimeError(\'required-Encore-runtime-not-stable\')\n checked_file({\'path\':\'/opt/tp-community-main-20261028/compose.encore.private.json\',\'sha256\':e[\'compose_sha256\']})\n # Root must have completed authenticated owner validation, not just a 401 probe.\n if e.get(\'authenticated_owner_acceptance\') is not True:raise RuntimeError(\'Encore-authenticated-owner-acceptance-required\')\n\ndef verify_bundle(bundle,manifest_sha):\n required={\'ThingsPanel-Go\',\'SOURCE_PROVENANCE.json\',\'SOURCE_FILES.json\',\'manifest.json\'}\n if bundle.is_symlink() or {p.name for p in bundle.iterdir()}!=required:raise RuntimeError(\'Gin-bundle-file-set-invalid\')\n if any(p.is_symlink() or not p.is_file() for p in bundle.iterdir()):raise RuntimeError(\'Gin-bundle-entry-invalid\')\n if manifest_sha!=MANIFEST_SHA or sha(bundle/\'manifest.json\')!=MANIFEST_SHA:raise RuntimeError(\'Gin-manifest-checksum-mismatch\')\n manifest=json.loads((bundle/\'manifest.json\').read_text())\n if manifest[\'commit\']!=CANDIDATE or manifest[\'backend_version\']!=\'gin-cas-command-\'+CANDIDATE:raise RuntimeError(\'Gin-candidate-identity-mismatch\')\n if any(manifest.get(k) is not False for k in (\'encore_changed\',\'broker_changed\',\'migration_required\')):raise RuntimeError(\'Gin-candidate-scope-invalid\')\n if set(manifest[\'sha256\'])!=required-{\'manifest.json\'}:raise RuntimeError(\'Gin-checksum-file-set-invalid\')\n if manifest[\'sha256\'][\'ThingsPanel-Go\']!=NEXT_SHA:raise RuntimeError(\'Gin-binary-identity-mismatch\')\n for name,digest in manifest[\'sha256\'].items():\n  if sha(bundle/name)!=digest:raise RuntimeError(\'Gin-artifact-checksum-mismatch\')\n p=json.loads((bundle/\'SOURCE_PROVENANCE.json\').read_text())\n if (p[\'candidate_commit\'],p[\'base_composition_commit\'],p[\'cas_source_commit\'],p[\'command_source_commit\'])!=(CANDIDATE,BASE,CAS,COMMAND):raise RuntimeError(\'Gin-source-provenance-mismatch\')\n if len(p[\'changes\'])!=20 or {x[\'path\'] for x in p[\'changes\']}!=EXPECTED_CHANGES:raise RuntimeError(\'Gin-source-change-scope-mismatch\')\n if p[\'unchanged_file_count\']!=1981 or p[\'unchanged_broker_file_count\']!=1660 or any(p[k] for k in (\'broker_changed\',\'encore_changed\',\'database_owner_changed\',\'command_anchor_merged\')):\n  raise RuntimeError(\'Gin-retained-baseline-proof-mismatch\')\n sources=json.loads((bundle/\'SOURCE_FILES.json\').read_text())\n if any(sources.get(x[\'path\'])!=x[\'after_sha256\'] for x in p[\'changes\']):raise RuntimeError(\'Gin-source-file-proof-mismatch\')\n return manifest\n\ndef baseline(spec):\n preserve(spec)\n checked_file({\'path\':str(BINARY),\'sha256\':OLD_SHA})\n p=process()\n if p[\'pid\']!=OLD_PID or p[\'pm2_env\'][\'status\']!=\'online\' or pathlib.Path(p[\'pm2_env\'][\'pm_exec_path\'])!=BINARY:\n  raise RuntimeError(\'Gin-baseline-process-drift\')\n return p\n\ndef stage_release(bundle,stage,spec,manifest_sha):\n p=baseline(spec);manifest=verify_bundle(bundle,manifest_sha)\n if stage.exists() or stage.is_symlink():raise RuntimeError(\'refusing-existing-Gin-stage\')\n size=(bundle/\'ThingsPanel-Go\').stat().st_size+BINARY.stat().st_size\n if shutil.disk_usage(str(ROOT)).free<size+128*1024**2 or shutil.disk_usage(str(BINARY.parent)).free<size+128*1024**2:\n  raise RuntimeError(\'insufficient-Gin-release-rollback-capacity\')\n # Discover the existing config, preserving args and environment unchanged.\n args=p[\'pm2_env\'].get(\'args\') or []\n if isinstance(args,str):\n  import shlex\n  args=shlex.split(args)\n configs=[pathlib.Path(p[\'pm2_env\'][\'pm_cwd\'])/\'configs/conf.yml\']\n for i,a in enumerate(args):\n  if a in (\'-config\',\'--config\'):\n   if i+1>=len(args):raise RuntimeError(\'invalid-current-config-args\')\n   configs=[pathlib.Path(args[i+1])]\n  elif a.startswith((\'-config=\',\'--config=\')):configs=[pathlib.Path(a.split(\'=\',1)[1])]\n config=configs[0]\n if not config.is_absolute():config=pathlib.Path(p[\'pm2_env\'][\'pm_cwd\'])/config\n if config.is_symlink() or not config.is_file():raise RuntimeError(\'current-config-not-regular-file\')\n stage.mkdir(mode=0o700)\n private(stage/\'backend.before\',BINARY.read_bytes())\n private(stage/\'backend.next\',(bundle/\'ThingsPanel-Go\').read_bytes());(stage/\'backend.next\').chmod(0o700)\n expected=\'gin-cas-command-\'+CANDIDATE\n if run([stage/\'backend.next\',\'--version\']).decode().strip()!=expected:raise RuntimeError(\'candidate-binary-version-mismatch\')\n old_version=run([BINARY,\'--version\']).decode().strip()\n record(stage/\'pm2.before.private.json\',p)\n state={\'candidate\':CANDIDATE,\'spec\':spec,\'manifest_sha256\':manifest_sha,\'old_sha256\':OLD_SHA,\'next_sha256\':manifest[\'sha256\'][\'ThingsPanel-Go\'],\'old_version\':old_version,\'next_version\':expected,\'old_pid\':OLD_PID,\'pm_id\':PM_ID,\'process_contract\':process_contract(p),\'config\':{\'path\':str(config),\'sha256\':sha(config)}}\n record(stage/\'state.private.json\',state)\n baseline(spec)\n return {\'status\':\'STAGED_NOT_APPLIED\',\'candidate\':CANDIDATE,\'old_binary_sha256\':OLD_SHA,\'next_binary_sha256\':state[\'next_sha256\'],\'process_contract_sha256\':state[\'process_contract\']}\n\ndef atomic_binary(source,expected,stage):\n checked_file({\'path\':str(BINARY),\'sha256\':expected})\n st=BINARY.stat();temp=BINARY.with_name(BINARY.name+\'.\'+stage.name+\'.next\')\n private(temp,source.read_bytes());os.chmod(temp,st.st_mode&0o777);os.chown(temp,st.st_uid,st.st_gid)\n if sha(BINARY)!=expected:raise RuntimeError(\'Gin-binary-drift-before-replace\')\n os.replace(str(temp),str(BINARY))\n fd=os.open(str(BINARY.parent),os.O_DIRECTORY)\n try:os.fsync(fd)\n finally:os.close(fd)\n\ndef retained(state):\n preserve(state[\'spec\']);checked_file(state[\'config\'])\n p=process()\n if process_contract(p)!=state[\'process_contract\']:raise RuntimeError(\'PM2-env-or-config-drift\')\n return p\n\ndef ready(state,version,expected_hash):\n deadline=time.monotonic()+45;stable=None;pid=None\n while time.monotonic()<deadline:\n  try:\n   p=retained(state)\n   if p[\'pm2_env\'][\'status\']!=\'online\' or not p.get(\'pid\'):raise RuntimeError(\'Gin-not-online\')\n   checked_file({\'path\':str(BINARY),\'sha256\':expected_hash})\n   with urllib.request.urlopen(\'http://127.0.0.1:9999/api/v1/sys_version\',timeout=3) as r:\n    if json.load(r).get(\'data\',{}).get(\'version\')!=version:raise RuntimeError(\'Gin-version-not-ready\')\n   if pid!=p[\'pid\']:pid=p[\'pid\'];stable=time.monotonic()\n   if time.monotonic()-stable>=8:return p\n  except Exception:stable=None;pid=None\n  time.sleep(1)\n raise RuntimeError(\'Gin-bounded-readiness-failed\')\n\ndef apply_release(stage,rollback=False):\n state=json.loads((stage/\'state.private.json\').read_text())\n if state[\'candidate\']!=CANDIDATE or state[\'old_sha256\']!=OLD_SHA:raise RuntimeError(\'Gin-private-stage-identity-mismatch\')\n for name,digest in [(\'backend.before\',state[\'old_sha256\']),(\'backend.next\',state[\'next_sha256\'])]:checked_file({\'path\':str(stage/name),\'sha256\':digest})\n p=retained(state)\n if rollback:\n  applied=json.loads((stage/\'applied.private.json\').read_text())\n  if p[\'pid\']!=applied[\'pid\'] or sha(BINARY)!=state[\'next_sha256\']:raise RuntimeError(\'rollback-refuses-intervening-Gin-deployment\')\n  atomic_binary(stage/\'backend.before\',state[\'next_sha256\'],stage)\n  run([PM2,\'restart\',str(PM_ID)],timeout=45)\n  ready(state,state[\'old_version\'],state[\'old_sha256\'])\n  return {\'status\':\'ROLLED_BACK_GIN_ONLY\',\'version\':state[\'old_version\']}\n if p[\'pid\']!=OLD_PID or sha(BINARY)!=OLD_SHA:raise RuntimeError(\'Gin-changed-since-staging\')\n try:\n  atomic_binary(stage/\'backend.next\',OLD_SHA,stage)\n  run([PM2,\'restart\',str(PM_ID)],timeout=45)\n  current=ready(state,state[\'next_version\'],state[\'next_sha256\'])\n  record(stage/\'applied.private.json\',{\'pid\':current[\'pid\'],\'version\':state[\'next_version\'],\'binary_sha256\':state[\'next_sha256\']})\n  return {\'status\':\'APPLIED_GIN_INITIAL_HEALTH\',\'version\':state[\'next_version\'],\'acceptance\':\'PENDING_POST_LOCK_CAS_AND_NATIVE_COMMAND_TESTS\'}\n except Exception as error:\n  # Never roll back an unrelated replacement or altered PM2/config contract.\n  retained(state)\n  if sha(BINARY)!=state[\'next_sha256\']:raise RuntimeError(\'Gin-apply-failed-rollback-blocked-by-drift\')\n  atomic_binary(stage/\'backend.before\',state[\'next_sha256\'],stage)\n  run([PM2,\'restart\',str(PM_ID)],timeout=45)\n  ready(state,state[\'old_version\'],state[\'old_sha256\'])\n  return {\'status\':\'GIN_APPLY_FAILED_ROLLED_BACK\',\'cause_type\':type(error).__name__}\n\ndef main():\n p=argparse.ArgumentParser();p.add_argument(\'mode\',choices=[\'stage\',\'apply\',\'rollback\']);p.add_argument(\'--stage\',required=True);p.add_argument(\'--bundle\');p.add_argument(\'--spec\');p.add_argument(\'--manifest-sha\')\n a=p.parse_args();stage=pathlib.Path(a.stage)\n if ROOT.is_symlink() or ROOT.resolve()!=ROOT or stage.parent!=ROOT or not re.fullmatch(r\'q02-gin-[a-zA-Z0-9-]+\',stage.name):raise RuntimeError(\'explicit-stage-path-required\')\n if LOCK.is_symlink():raise RuntimeError(\'deployment-lock-symlink\')\n with LOCK.open(\'r\') as lock:\n  fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)\n  if a.mode==\'stage\':\n   if not a.bundle or not a.spec or not re.fullmatch(\'[0-9a-f]{64}\',a.manifest_sha or \'\'):raise RuntimeError(\'explicit-stage-inputs-required\')\n   result=stage_release(pathlib.Path(a.bundle),stage,json.loads(pathlib.Path(a.spec).read_text()),a.manifest_sha)\n  else:result=apply_release(stage,a.mode==\'rollback\')\n print(json.dumps(result))\n if result[\'status\']==\'GIN_APPLY_FAILED_ROLLED_BACK\':raise SystemExit(1)\n\nif __name__==\'__main__\':main()\n'
